4	/// The cameras (camera-recording CR1a, spec §11 CAM-3): which are connected,
5	/// what each offers, which one a name or id means, which is the default, and
6	/// the format a recording is made at, and the Format popup's rows (CR2a,
7	/// CAM-6). Only `connected()`, `facts(of:)` and
8	/// `device(withID:)` touch the framework; the rule, the spelling, the rate,
9	/// the lookup and the default are PURE functions over `CameraDeviceFacts`,
10	/// so `tools/proof/camera_recording_probe.py` pins them on CR0's own format
11	/// lists without a camera.
12	///
13	/// **No Continuity key** (CR0's D2): the discovery asks for
14	/// `.builtInWideAngleCamera` and `.external` only — never `.continuityCamera`,
15	/// and the Info.plist has no `NSCameraUseContinuityCameraDeviceType` — and an
16	/// iPhone's Continuity Camera is listed all the same. Listing a device opens
17	/// nothing and needs no grant.
18	
19	/// One format as the recorder reads it: its size and its highest frame rate.
20	struct CameraFormatFacts: Equatable {
21	    let width: Int
22	    let height: Int
23	    let maxRate: Double
24	}
25	
26	/// One connected camera as the recorder reads it. `formats` is the device's
27	/// own list, in its own order; `activeFormat` an index into it;
28	/// `isContinuityCamera` the system's own mark (CAM-6 (5)).
29	struct CameraDeviceFacts: Equatable {
30	    let uniqueID: String
31	    let name: String
32	    let isBuiltIn: Bool
33	    let formats: [CameraFormatFacts]
34	    let activeFormat: Int?
35	    var isContinuityCamera: Bool = false
36	}
37	
38	enum CameraDevices {
39	    /// The cameras connected now, the discovery session's own order, keeping
40	    /// only those whose `isConnected` is true (spec §11 CAM-8 (5)): the
41	    /// panel, the tool's lookup, the default and the recorder's start all
42	    /// read this one list.
43	    static func connected() -> [AVCaptureDevice] {
44	        AVCaptureDevice.DiscoverySession(
45	            deviceTypes: [.builtInWideAngleCamera, .external], mediaType: .video,
46	            position: .unspecified
47	        ).devices.filter(\.isConnected)
48	    }
49	
50	    /// `device`'s facts: each format's dimensions and the highest maximum of
51	    /// its frame-rate ranges, and the index of the active one.
52	    static func facts(of device: AVCaptureDevice) -> CameraDeviceFacts {
53	        let formats = device.formats.map { format -> CameraFormatFacts in
54	            let size = CMVideoFormatDescriptionGetDimensions(format.formatDescription)
55	            let rate = format.videoSupportedFrameRateRanges.map(\.maxFrameRate).max() ?? 0
56	            return CameraFormatFacts(width: Int(size.width), height: Int(size.height), maxRate: rate)
57	        }
58	        return CameraDeviceFacts(
59	            uniqueID: device.uniqueID, name: device.localizedName,
60	            isBuiltIn: device.deviceType == .builtInWideAngleCamera, formats: formats,
61	            activeFormat: device.formats.firstIndex { $0 == device.activeFormat },
62	            isContinuityCamera: device.isContinuityCamera)
63	    }
64	
65	    /// The connected camera whose `uniqueID` is `id`, or nil.
66	    static func device(withID id: String) -> AVCaptureDevice? {
67	        connected().first { $0.uniqueID == id }
68	    }
69	
70	    // MARK: - The format (CAM-3)
71	
72	    /// CAM-3's best format: CAM-2's rule over the formats WIDER THAN TALL;
73	    /// if none qualifies, CAM-2's rule over every format; if that finds none
74	    /// either, `active`. An index into `formats`, or nil.
75	    static func bestFormat(_ formats: [CameraFormatFacts], active: Int?) -> Int? {
76	        let landscape = formats.indices.filter { formats[$0].width > formats[$0].height }
77	        return largest(formats, among: landscape)
78	            ?? largest(formats, among: Array(formats.indices)) ?? active
79	    }
80	
81	    /// CAM-2's rule over `indices`: the largest width × height whose maximum
82	    /// rate is ≥ 30, ties to the higher maximum rate, then to the format
83	    /// listed first.
84	    private static func largest(_ formats: [CameraFormatFacts], among indices: [Int]) -> Int? {
85	        var best: Int?
86	        for index in indices where formats[index].maxRate >= 30 {
87	            guard let current = best else {
88	                best = index
89	                continue
90	            }
91	            let area = formats[index].width * formats[index].height
92	            let bestArea = formats[current].width * formats[current].height
93	            if area > bestArea
94	                || (area == bestArea && formats[index].maxRate > formats[current].maxRate)
95	            {
96	                best = index
97	            }
98	        }
99	        return best
100	    }
101	
102	    /// The canvas rate of a new project made around a recording at `format`:
103	    /// its maximum rate, rounded, at least 1 (CAM-3's Canvas).
104	    static func canvasRate(_ format: CameraFormatFacts) -> Int {
105	        max(1, Int(format.maxRate.rounded()))
106	    }
107	
108	    /// `1920x1080@30` — the format as the result and the tool spell it, the
109	    /// rate written `%g`.
110	    static func spelled(_ format: CameraFormatFacts) -> String {
111	        "\(format.width)x\(format.height)@" + String(format: "%g", format.maxRate)
112	    }
113	
114	    // MARK: - The chosen format (CAM-6)
115	
116	    /// CAM-6 (1)'s rows after Best: one per distinct (width, height,
117	    /// maxRate) with maxRate > 0, the first listed kept; wider than tall,
118	    /// then square, then taller than wide, each by area then maxRate
119	    /// descending, then the device's order. Indices into `formats`.
120	    static func formatRows(_ formats: [CameraFormatFacts]) -> [Int] {
121	        var seen: [CameraFormatFacts] = []
122	        var rows: [Int] = []
123	        for index in formats.indices where formats[index].maxRate > 0 {
124	            guard !seen.contains(formats[index]) else { continue }
125	            seen.append(formats[index])
126	            rows.append(index)
127	        }
